cat > /tmp/verify/list_output.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    await page.goto('http://localhost/examples/spotify/indexSpotify.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(2500);
    const outputOpts = await page.$eval('#outputControls select', el => Array.from(el.options).map(o => ({v:o.value, t:o.textContent.trim()}))).catch(e => ['ERR '+e.message]);
    console.log('OUTPUT_OPTIONS:' + JSON.stringify(outputOpts, null, 2));
    await browser.close();
})().catch(e => { console.error('ERR', e.message); process.exit(1); });
EOF
cd /tmp/verify && node list_output.js 2>&1 | tail -40
